def load(path):
    raw = open(path, 'rb').read().decode('utf-8')
    return raw.replace('\r\n', '\n'), '\r\n' in raw

def main():
    try:
        t, _ = load('lib/models/radio_country.dart')
        if "code: 'DZ'" in t:
            print('이미 적용돼 있어요'); return
    except FileNotFoundError:
        print('❌ 프로젝트 폴더(mp3_player_new)에서 실행해 주세요'); sys.exit(1)
    out = {}
    ok = True
    for path, edits in EDITS.items():
        name = os.path.basename(path)
        if not os.path.exists(path):
            print(f'❌ {name} 파일이 없어요'); ok = False; continue
        t, crlf = load(path)
        for label, old, new in edits:
            c = t.count(old)
            if c == 1:
                t = t.replace(old, new); print(f'✔ {name}: {label}')
            else:
                print(f'❌ {name}: {label} — 찾을 곳을 못 찾았어요 ({c}곳)'); ok = False
        out[path] = (t, crlf)
    for lang, fn in LANG_FILE.items():
        path = f'lib/l10n/{fn}'
        if not os.path.exists(path):
            print(f'❌ {fn} 파일이 없어요'); ok = False; continue
        t, crlf = load(path)
        lines = t.split('\n')
        idx = [i for i, l in enumerate(lines) if l.startswith('  "countryPR":')]
        if len(idx) != 1 or '"countryDZ"' in t:
            print(f'❌ {fn}: 넣을 자리(countryPR)를 못 찾았어요'); ok = False; continue
        lines.insert(idx[0] + 1, ARB[lang].rstrip('\n'))
        out[path] = ('\n'.join(lines), crlf)
        print(f'✔ {fn}: 나라 이름 13개')
    if not ok:
        print('\n❌ 못 찾은 곳이 있어서 아무것도 저장하지 않았어요'); sys.exit(1)
    for path, (t, crlf) in out.items():
        open(path, 'wb').write((t.replace('\n', '\r\n') if crlf else t).encode('utf-8'))
    print('\n완료! (나라 13개 추가)')

main()
